<template><MerchantShell title="门店退款处理" :manager="manager"><template v-if="order"><view class="merchant-card"><text class="merchant-subtitle">{{ order.order_id }}</text><text>原实付款 ¥{{ order.pay_price }}</text><view class="merchant-warning">退款申请和资金执行是两次独立确认。创建申请不会自动退款。</view><view class="merchant-tabs"><button :class="{active:mode==='create'}" :disabled="!order.actions.refund_create.available" @tap="setMode('create')">发起退款申请</button><button :class="{active:mode==='review'}" :disabled="!order.actions.refund_decide.available" @tap="setMode('review')">处理已有申请</button></view></view><view v-if="resultMessage" class="merchant-warning" data-merchant="refund-result">{{ resultMessage }}<button @tap="manager.go('orders')">返回管理列表核对履约订单</button></view><template v-if="mode==='create'"><view class="merchant-card"><text class="merchant-subtitle">退款商品范围</text><view class="merchant-tabs"><button :class="{active:selectionMode==='remaining'}" @tap="chooseSelection('remaining')">全部剩余可退商品</button><button :class="{active:selectionMode==='items'}" @tap="chooseSelection('items')">按商品数量退款</button></view><view v-for="cart in order.cartInfo.filter(item=>!item.is_gift)" :key="cart.id"><MerchantCart :cart="cart" /><view v-if="selectionMode==='items'" class="merchant-choice"><view class="merchant-check" :class="{on:!!quantities[cart.id]}" @tap="toggle(cart)">{{ quantities[cart.id] ? '✓' : '' }}</view><text class="merchant-choice-label">剩余 {{ remaining(cart) }} 件</text><button :disabled="!quantities[cart.id] || (quantities[cart.id] || 0)<=1" @tap="quantity(cart,-1)">−</button><text>{{ quantities[cart.id]||0 }}</text><button :disabled="(quantities[cart.id] || 0)>=remaining(cart)" @tap="quantity(cart,1)">＋</button></view></view><button class="merchant-full-button" :disabled="reading || manager.busy.value || !order.actions.refund_create.available" @tap="getQuote">{{ reading ? '核对中…' : '核对可退金额' }}</button></view><view v-if="quote" class="merchant-card"><text class="merchant-subtitle">当前可退金额 ¥{{ quote.quoted_price }}</text><text class="merchant-note">适用退款时限 {{ quote.refund_time_days }} 天，请核对实际商品范围。</text><view class="merchant-form-field"><text>本次申请退款金额（元）</text><input v-model="refundPrice" type="digit" maxlength="15" /></view><view class="merchant-form-field"><text>退款原因</text><textarea v-model="reason" :maxlength="200" placeholder="填写此次退款原因" /></view><button class="merchant-full-button" :disabled="manager.busy.value || !manager.context.value?.data.capabilities.refund_create || !order.actions.refund_create.available" @tap="create">创建退款申请</button></view></template><template v-else><view class="merchant-card"><text class="merchant-subtitle">选择退款申请</text><view v-for="refund in order.refund" :key="refund.id" class="merchant-row"><text>{{ refund.order_id }} · ¥{{ refund.refund_price }}</text><button :disabled="reading || manager.busy.value" @tap="selectRefund(refund.id)">{{ review?.refund_id===refund.id ? '当前申请' : '读取核对' }}</button></view><text v-if="!order.refund.length" class="merchant-note">当前订单没有可读取的退款申请，请刷新后查看。</text></view><view v-if="review" class="merchant-card"><text class="merchant-subtitle">退款申请 {{ review.refund_order_id }}</text><view class="merchant-row"><text>申请金额</text><text>¥{{ review.refund_price }}</text></view><view class="merchant-row"><text>已退金额</text><text>¥{{ review.refunded_price }}</text></view><view class="merchant-row"><text>申请类型 / 当前状态</text><text>{{ applyLabel(review.apply_type) }} / {{ reviewLabel(review.refund_type) }}</text></view><view class="merchant-row"><text>申请时间</text><text>{{ merchantDate(review.add_time) }}</text></view><view v-if="review.refunded_time" class="merchant-row"><text>退款时间</text><text>{{ merchantDate(review.refunded_time) }}</text></view><view v-if="review.refund_reason" class="merchant-note">申请原因：{{ review.refund_reason }}</view><view v-if="review.refund_explain || review.refund_reason_wap_explain" class="merchant-note">申请说明：{{ review.refund_explain || review.refund_reason_wap_explain }}</view><view v-if="review.refuse_reason" class="merchant-warning">此前拒绝原因：{{ review.refuse_reason }}</view><view v-if="review.request_images.length" class="merchant-images"><image v-for="pic in review.request_images" :key="pic.url" :src="pic.src" mode="aspectFill" @tap="previewReview(pic.src,'request')" /></view><text v-if="review.request_images_error" class="merchant-note">申请凭证暂不可用，请核对原申请。</text><view v-if="review.return_logistics.express || review.return_logistics.express_name || review.return_logistics.explain" class="merchant-card"><text class="merchant-subtitle">退货物流</text><text>{{ review.return_logistics.express_name }} {{ review.return_logistics.express }}</text><text class="merchant-note">{{ review.return_logistics.phone }} · {{ review.return_logistics.explain }}</text></view><view v-if="review.return_images.length" class="merchant-images"><image v-for="pic in review.return_images" :key="pic.url" :src="pic.src" mode="aspectFill" @tap="previewReview(pic.src,'return')" /></view><text v-if="review.return_images_error" class="merchant-note">退货凭证暂不可用，请核对实际收货情况。</text><view v-if="review.requires_received_confirmation" class="merchant-choice"><view class="merchant-check" :class="{on:received}" @tap="received=!received">{{ received ? '✓' : '' }}</view><text>我已实际收到并验收此次退货商品</text></view><view class="merchant-form-field"><text>拒绝原因（拒绝时必填）</text><textarea v-model="refusal" :maxlength="200" /></view><view class="merchant-action-grid"><view v-for="action in reviewButtons" :key="action.kind" class="merchant-action-wrap"><button :disabled="manager.busy.value || !manager.context.value?.data.capabilities.refund_decide || !review.actions[action.kind].available || action.kind==='refund_execute' && review.requires_received_confirmation && !received" @tap="decide(action.kind)">{{ action.label }}</button><text v-if="!review.actions[action.kind].available" class="merchant-action-reason">{{ review.actions[action.kind].reason }}</text></view></view><view class="merchant-warning">余额退款以资金凭据确认。外部支付渠道的“已受理”仍需读取真实结算状态。</view></view></template><view v-if="error" class="merchant-warning">{{ error }}</view></template></MerchantShell></template>
<script setup lang="ts">
import { ref } from 'vue';import MerchantShell from '@/components/merchantOrders/MerchantShell.vue';import MerchantCart from '@/components/merchantOrders/MerchantCart.vue';import { useMerchantOrders } from '@/composables/useMerchantOrders';import { isMerchantDetail,merchantOrderId,merchantMoney,merchantMoneyInput,merchantDate } from '@/utils/merchantOrders';import { isUserCenterPublicImage } from '../../../../common/userCenterDesign';import type { MerchantRefundQuote,MerchantRefundReview } from '../../../../common/merchantManagement';import type { MerchantOrderDetail,MerchantOrderCart } from '@/types/merchantOrders';
type Quote=MerchantRefundQuote;
type Decision='return_approve'|'refund_refuse'|'refund_execute';
type Review=MerchantRefundReview;
const order=ref<MerchantOrderDetail|null>(null),mode=ref<'create'|'review'>('create'),selectionMode=ref<'remaining'|'items'>('remaining'),quantities=ref<Record<number,number>>({}),quote=ref<Quote|null>(null),review=ref<Review|null>(null),refundPrice=ref(''),reason=ref(''),refusal=ref(''),received=ref(false),reading=ref(false),error=ref(''),resultMessage=ref('');let orderId='',refundId=0,readEpoch=0;
const reviewButtons=[{kind:'return_approve' as const,label:'同意退货'},{kind:'refund_refuse' as const,label:'拒绝申请'},{kind:'refund_execute' as const,label:'确认执行退款'}];
const manager=useMerchantOrders({query(query){orderId=query.orderId||query.id||'';mode.value=query.mode==='review'?'review':'create';refundId=Number(query.refund_id)||0;},clear(){readEpoch++;order.value=null;quote.value=null;review.value=null;quantities.value={};refundPrice.value='';reason.value='';refusal.value='';received.value=false;reading.value=false;error.value='';resultMessage.value='';},async load(controller){const valid=controller.fence();if(!merchantOrderId(orderId))throw Error('订单编号无效');const value=await controller.read(`detail/${encodeURIComponent(orderId)}`,isMerchantDetail);if(!valid())return;if(value.data.order_id!==orderId)throw Error('订单响应不匹配');order.value=value.data;if(mode.value==='review'&&refundId)await getReview(refundId);}});
const record=(value:unknown):value is Record<string,unknown>=>!!value&&typeof value==='object'&&!Array.isArray(value),int=(value:unknown,min=0)=>typeof value==='number'&&Number.isSafeInteger(value)&&value>=min,hash=(value:unknown)=>typeof value==='string'&&/^[a-f0-9]{64}$/u.test(value),text=(value:unknown,max=500)=>typeof value==='string'&&value.length<=max&&!/[\u0000-\u001f\u007f]/u.test(value);
function authorityMatches(value:Record<string,unknown>){return value.actor_uid===manager.auth.uid&&value.store_id===order.value?.store_id&&value.order_id===order.value?.id&&value.scope_key===manager.context.value?.scope_key&&hash(value.expected_order_revision)&&value.expected_order_revision===order.value?.revision;}
function isQuote(value:unknown):value is Quote{return record(value)&&value.version==='merchant-refund-quote-v1'&&authorityMatches(value)&&value.mode===selectionMode.value&&Array.isArray(value.items)&&value.items.length<=100&&value.items.every(item=>record(item)&&int(item.cart_id,1)&&int(item.cart_num,1))&&new Set(value.items.map(item=>item.cart_id)).size===value.items.length&&merchantMoney(value.quoted_price)&&hash(value.quote_fingerprint)&&int(value.refund_time_days);}
function isReview(value:unknown):value is Review{return record(value)&&value.version==='merchant-refund-review-v1'&&authorityMatches(value)&&int(value.refund_id,1)&&merchantOrderId(value.refund_order_id)&&merchantMoney(value.refund_price)&&merchantMoney(value.refunded_price)&&[1,2,3,4].includes(Number(value.apply_type))&&[0,1,2,3,4,5,6].includes(Number(value.refund_type))&&['refund_reason','refund_explain','refuse_reason','refund_reason_wap_explain'].every(key=>typeof value[key]==='string'&&String(value[key]).length<=10000&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u.test(String(value[key])))&&['add_time','refunded_time','refund_reason_time'].every(key=>int(value[key]))&&record(value.return_logistics)&&['express','express_name','phone','explain'].every(key=>text((value.return_logistics as Record<string,unknown>)[key],10000))&&['request_images','return_images'].every(key=>Array.isArray(value[key])&&(value[key] as unknown[]).length<=3&&(value[key] as unknown[]).every(pic=>record(pic)&&typeof pic.url==='string'&&/^\/api\/assets\/[1-9]\d*$/u.test(pic.url)&&isUserCenterPublicImage(pic.src)))&&text(value.request_images_error)&&text(value.return_images_error)&&hash(value.review_fingerprint)&&typeof value.requires_received_confirmation==='boolean'&&record(value.actions)&&reviewButtons.every(action=>{const rule=(value.actions as Record<string,unknown>)[action.kind];return record(rule)&&typeof rule.available==='boolean'&&text(rule.reason);});}
function clearQuote(){readEpoch++;quote.value=null;refundPrice.value='';error.value='';}function remaining(cart:MerchantOrderCart){return Math.max(0,cart.cart_num-cart.refund_num);}function toggle(cart:MerchantOrderCart){clearQuote();quantities.value[cart.id]=quantities.value[cart.id]?0:remaining(cart);}function quantity(cart:MerchantOrderCart,delta:number){clearQuote();quantities.value[cart.id]=Math.max(0,Math.min(remaining(cart),(quantities.value[cart.id]||0)+delta));}function chooseSelection(value:'remaining'|'items'){selectionMode.value=value;clearQuote();}function setMode(value:'create'|'review'){mode.value=value;clearQuote();review.value=null;received.value=false;refusal.value='';}
function items(){return selectionMode.value==='remaining'?[]:(order.value?.cartInfo||[]).filter(cart=>(quantities.value[cart.id]||0)>0&&!cart.is_gift).map(cart=>({cart_id:cart.id,cart_num:quantities.value[cart.id]!}));}
async function getQuote(){const detail=order.value,scope=manager.context.value;if(!detail||!scope||reading.value||!detail.actions.refund_create.available)return;quote.value=null;error.value='';reading.value=true;const valid=manager.fence(),epoch=++readEpoch,chosen=items();try{if(selectionMode.value==='items'&&!chosen.length)throw Error('请选择退款商品和数量');const result=await manager.financialRead('refund/quote',isQuote,{version:'merchant-refund-quote-v1',store_id:detail.store_id,scope_key:scope.scope_key,order_id:detail.id,expected_order_revision:detail.revision,mode:selectionMode.value,items:chosen});if(!valid()||epoch!==readEpoch)return;if(selectionMode.value==='items'&&(result.items.length!==chosen.length||result.items.some(row=>!chosen.some(selected=>selected.cart_id===row.cart_id&&selected.cart_num===row.cart_num))))throw Error('退款商品报价不匹配，请重新核对');quote.value=result;refundPrice.value=result.quoted_price;}catch(failure){if(valid()&&epoch===readEpoch)error.value=failure instanceof Error?failure.message:'报价读取失败';}finally{if(valid()&&epoch===readEpoch)reading.value=false;}}
async function getReview(id:number){const detail=order.value,scope=manager.context.value;if(!detail||!scope||reading.value)return;review.value=null;received.value=false;refusal.value='';reading.value=true;error.value='';const valid=manager.fence(),epoch=++readEpoch;try{const result=await manager.financialRead('refund/review',isReview,{version:'merchant-refund-review-v1',store_id:detail.store_id,scope_key:scope.scope_key,order_id:detail.id,refund_id:id});if(!valid()||epoch!==readEpoch)return;if(result.refund_id!==id)throw Error('退款申请响应不匹配');review.value=result;refundId=id;}catch(failure){if(valid()&&epoch===readEpoch)error.value=failure instanceof Error?failure.message:'退款核对失败';}finally{if(valid()&&epoch===readEpoch)reading.value=false;}}
function previewReview(pic:string,kind:'request'|'return'){const images=kind==='request'?review.value?.request_images:review.value?.return_images,urls=images?.map(image=>image.src)||[];if(manager.current()&&urls.includes(pic))uni.previewImage({current:pic,urls});}
function selectRefund(id:number){void getReview(id);}function wire(payload:Record<string,unknown>){const detail=order.value!,scope=manager.context.value!;return{version:'merchant-order-operation-v1',store_id:detail.store_id,scope_key:scope.scope_key,order_id:detail.id,expected_order_revision:detail.revision,payload};}
function plan(kind:string,payload:Record<string,unknown>,endpoint:string){return{action:kind,order_id:order.value!.order_id,endpoint:`/store/manager/order/financial/refund/${endpoint}`,body:wire(payload),receipt_path:'/store/manager/order/operation/{requestKey}',receipt_method:'GET' as const,abandon_path:`/store/manager/order/operation/abandon/${kind}`};}
async function confirm(title:string,content:string){return new Promise<boolean>(resolve=>uni.showModal({title,content,success:result=>resolve(result.confirm),fail:()=>resolve(false)}));}
async function create(){const value=quote.value,detail=order.value;if(!value||!detail||!detail.actions.refund_create.available||!manager.context.value?.data.capabilities.refund_create||manager.busy.value)return;error.value='';const valid=manager.fence();try{const refund_price=merchantMoneyInput(refundPrice.value),decimal=(money:string)=>Number(money.replace('.',''));if(decimal(refund_price)>decimal(merchantMoneyInput(value.quoted_price)))throw Error('退款金额不能超过此次商品报价');const why=reason.value.trim();if(!text(why,200)||!why)throw Error('请填写不超过 200 字的退款原因');if(!await confirm('创建退款申请',`本次申请 ¥${refund_price}。创建后需要另行核对并执行资金退款。`)||!valid())return;
  const result=await manager.execute(plan('refund_create',{mode:value.mode,items:value.mode==='remaining'?[]:items(),quoted_price:merchantMoneyInput(value.quoted_price),refund_price,quote_fingerprint:value.quote_fingerprint,reason:why},'create'));if(!valid()||!result)return;if(result.outcome!=='application-created'){error.value='退款申请未创建，请核对并确认原操作记录。';return;}const evidence=result.evidence as {refund_id?:unknown;refund_order_id?:unknown}|undefined;if(!evidence||!int(evidence.refund_id,1)||!merchantOrderId(evidence.refund_order_id))throw Error('申请凭据缺少新申请编号，请读取原操作结果');refundId=Number(evidence.refund_id);mode.value='review';const actor=manager.auth.uid,store=manager.selectedStore.value;await manager.load();if(manager.current()&&manager.auth.uid===actor&&manager.selectedStore.value===store)resultMessage.value='退款申请已创建，资金尚未退回。请核对下方申请并另行确认退款。';
}catch(failure){if(valid())error.value=manager.unresolved.value.some(intent=>intent.order_id===detail.order_id)?'原申请结果待确认，请查询原操作。':failure instanceof Error?failure.message:'尚未提交';}}
async function decide(kind:Decision){const value=review.value,detail=order.value;if(!value||!detail||!value.actions[kind].available||!manager.context.value?.data.capabilities.refund_decide||manager.busy.value)return;error.value='';const valid=manager.fence();try{if(kind==='refund_execute'&&value.requires_received_confirmation&&!received.value)throw Error('请先实际验收退货并勾选确认');const action=kind==='return_approve'?'return':kind==='refund_refuse'?'refuse':'refund',payload:Record<string,unknown>={action,refund_id:value.refund_id,review_fingerprint:value.review_fingerprint,decision:{apply_type:value.apply_type,refund_type:value.refund_type,received:received.value}};if(kind==='refund_refuse'){const why=refusal.value.trim();if(!text(why,200)||!why)throw Error('拒绝申请需填写不超过 200 字的原因');payload.reason=why;}if(!await confirm(kind==='refund_execute'?'确认执行真实退款':'确认处理申请',kind==='refund_execute'?`执行申请 ${value.refund_order_id}，金额 ¥${value.refund_price}。外部渠道受理不代表资金已到账。`:'将按当前核对的申请状态提交处理。')||!valid())return;
  const result=await manager.execute(plan(kind,payload,'execute'));if(!valid()||!result)return;if(['abandoned','rollback-rejected'].includes(result.outcome)){error.value='本次处理未执行，请核对并确认原操作记录。';return;}const message=result.outcome==='provider-admitted'?'退款渠道已受理，资金结果尚未确认。请重新读取申请和资金状态。':result.outcome==='balance-settled'?'资金退款已确认完成。':result.outcome==='return-approved'?'退货已同意。实际收到并验收商品后再确认退款。':result.outcome==='refused'?'申请已拒绝。':'';if(!message)throw Error('处理凭据状态尚未确认，请查询原操作');resultMessage.value=message;if(result.outcome==='balance-settled'||result.outcome==='provider-admitted'){quote.value=null;review.value=null;return;}const actor=manager.auth.uid,store=manager.selectedStore.value;await manager.load();if(manager.current()&&manager.auth.uid===actor&&manager.selectedStore.value===store)resultMessage.value=message;
}catch(failure){if(valid())error.value=manager.unresolved.value.some(intent=>intent.order_id===detail.order_id)?'原处理结果待确认，请查询原操作。':failure instanceof Error?failure.message:'尚未提交';}}
function applyLabel(value:number){return ({1:'仅退款',2:'退货退款',3:'售后退货',4:'商家主动退款'} as Record<number,string>)[value]||'退款申请';}function reviewLabel(value:number){return ({0:'待审核',1:'退款处理中',2:'退货退款处理中',3:'已拒绝',4:'待寄回退货',5:'已寄回待验收',6:'已退款'} as Record<number,string>)[value]||'待核对';}
</script>
